//! The Week tab's AI parts: Recommended tasks and the Work summary.
//!
//! Both are generated by `main.rs` on its own: when the Week tab is shown
//! (and on the minute tick while it is) for any report whose facts changed
//! since its newest version, and on the summary's schedule. There is no
//! Generate button: the panel only says what is happening ("Updating…"),
//! why it can't ("Can't update: the API key is locked."), or when it last
//! updated. A failed update shows the error and a Retry.
//!
//! - Recommended tasks: the newest `Plan` version, parsed with
//!   `report::parse_recommendations`. The Week tab draws the list and the
//!   rank badges in its day columns; this module only holds the parsed
//!   result and the status line.
//! - Work summary: the newest `Summary` version as Markdown, with Copy,
//!   Edit, Export and, for an edited summary, Discard edit (an edited
//!   summary is not regenerated, so the edit is never lost silently).
//!
//! `load` runs after every message and on every streamed piece, so it
//! returns early on equal data and only reparses Markdown whose source
//! changed; streamed text that grows is pushed incrementally.

use fortnight_core::domain::{Report, ReportId, ReportKind, ReportStatus, WeekRef};
use fortnight_core::export::ExportFormat;
use fortnight_core::report::{self, Recommendation};
use iced::widget::{Column, button, column, markdown, row, space, text, text_editor};
use iced::{Center, Element, Font, Padding, Theme, border, color};

use crate::theme;

#[derive(Debug, Clone)]
pub enum Message {
    /// Retry after a failed update.
    Retry(ReportKind),
    StartEdit,
    EditAction(text_editor::Action),
    SaveEdit,
    CancelEdit,
    DiscardEdit,
    Copy,
    Export,
    /// A Markdown link was clicked; ignored on purpose.
    LinkClicked(markdown::Uri),
}

/// What `main.rs` must do.
#[derive(Debug, Clone, PartialEq)]
pub enum Action {
    None,
    /// Generate this kind of report for this week now (Retry).
    Generate(ReportKind, WeekRef),
    /// Save the user's edit of a report version; `None` discards it.
    SaveEdit(ReportId, Option<String>),
    /// Copy this text to the clipboard.
    Copy(String),
    /// Export this report version to a file (`main.rs` asks where).
    Export(ReportId, ExportFormat),
}

/// One kind of report for the week.
#[derive(Debug, Clone, PartialEq)]
pub struct ReportSlot {
    pub kind: ReportKind,
    /// Every version, newest first (may include `Failed` ones).
    pub versions: Vec<Report>,
    /// `Some(text so far)` while a version is being generated (streamed).
    pub streaming: Option<String>,
    /// Why it can't be generated right now, e.g. "the API key is locked".
    pub blocked: Option<String>,
    /// There is nothing to summarise or recommend.
    pub empty: bool,
    /// The newest ready version no longer matches the tasks.
    pub stale: bool,
}

/// Everything the panel shows, supplied by `main.rs`.
#[derive(Debug, Clone, PartialEq)]
pub struct ReportPanelData {
    pub week: WeekRef,
    /// e.g. "Week 46 · Nov 9–15".
    pub week_label: String,
    /// A past week has `[Summary]`, the current week `[Plan, Summary]`, a
    /// future week `[Plan]`.
    pub slots: Vec<ReportSlot>,
}

#[derive(Debug, Default)]
pub struct ReportPanel {
    data: Option<ReportPanelData>,
    /// The newest ready plan, parsed.
    recommendation: Option<Recommendation>,
    /// The summary shown (streamed text while generating, otherwise the
    /// newest ready version), parsed, and its source.
    body: markdown::Content,
    body_src: String,
    /// How many times `body` was (re)parsed; for tests.
    body_parses: u32,
    /// The open editor and the version it edits.
    editor: Option<(ReportId, text_editor::Content)>,
}

/// A status line under a heading, and whether it is an error.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Status {
    pub text: String,
    pub error: bool,
    /// Offer Retry.
    pub retry: bool,
}

impl ReportPanel {
    pub fn new() -> Self {
        Self::default()
    }

    /// Replaces what the panel shows. Cheap when `data` is unchanged; keeps
    /// an open editor unless its version is no longer the newest ready one
    /// or the week changed.
    pub fn load(&mut self, data: ReportPanelData) {
        if self.data.as_ref() == Some(&data) {
            return;
        }
        let same_week = self.data.as_ref().map(|d| d.week) == Some(data.week);
        self.data = Some(data);
        let newest = self.ready(ReportKind::Summary).map(|r| r.id);
        if !same_week || self.editor.as_ref().map(|(id, _)| Some(*id)) != Some(newest) {
            self.editor = None;
        }
        self.recommendation = self
            .ready(ReportKind::Plan)
            .and_then(Report::text)
            .and_then(report::parse_recommendations);
        self.refresh();
    }

    fn refresh(&mut self) {
        let body_src = match self.slot(ReportKind::Summary) {
            Some(slot) => match &slot.streaming {
                Some(so_far) => so_far.clone(),
                None => self
                    .ready(ReportKind::Summary)
                    .and_then(Report::text)
                    .unwrap_or_default()
                    .to_owned(),
            },
            None => String::new(),
        };
        if body_src != self.body_src {
            match body_src.strip_prefix(self.body_src.as_str()) {
                Some(more) if !self.body_src.is_empty() => self.body.push_str(more),
                _ => self.body = markdown::Content::parse(&body_src),
            }
            self.body_src = body_src;
            self.body_parses += 1;
        }
    }

    pub fn slot(&self, kind: ReportKind) -> Option<&ReportSlot> {
        self.data.as_ref()?.slots.iter().find(|s| s.kind == kind)
    }

    /// The newest ready version of `kind`.
    fn ready(&self, kind: ReportKind) -> Option<&Report> {
        self.slot(kind)?
            .versions
            .iter()
            .find(|r| r.status == ReportStatus::Ready)
    }

    /// The parsed recommended tasks, if there is a ready plan.
    pub fn recommendation(&self) -> Option<&Recommendation> {
        self.recommendation.as_ref()
    }

    /// The newest ready plan's text when it isn't the expected JSON (shown
    /// as it is).
    pub fn unparsed_plan(&self) -> Option<&str> {
        match self.recommendation {
            Some(_) => None,
            None => self.ready(ReportKind::Plan).and_then(Report::text),
        }
    }

    /// The text in the open editor, if editing.
    pub fn editor_text(&self) -> Option<String> {
        self.editor.as_ref().map(|(_, c)| c.text())
    }

    /// What the status line under `kind`'s heading says, if anything.
    pub fn status(&self, kind: ReportKind) -> Option<Status> {
        let slot = self.slot(kind)?;
        let plain = |s: String| {
            Some(Status {
                text: s,
                error: false,
                retry: false,
            })
        };
        if slot.streaming.is_some() {
            return plain("Updating…".into());
        }
        let ready = self.ready(kind);
        if let Some(reason) = &slot.blocked
            && (ready.is_none() || slot.stale)
        {
            return plain(format!("Can't update: {reason}"));
        }
        if let Some(newest) = slot.versions.first()
            && newest.status == ReportStatus::Failed
            && slot.stale
        {
            let error = newest.error.as_deref().unwrap_or("unknown error");
            return Some(Status {
                text: format!("Couldn't update: {}", first_line(error)),
                error: true,
                retry: slot.blocked.is_none(),
            });
        }
        match ready {
            None if slot.empty => plain(
                match kind {
                    ReportKind::Plan => "No open tasks to recommend.",
                    ReportKind::Summary => "Nothing done this week yet.",
                }
                .into(),
            ),
            None => None,
            Some(r) => {
                let mut s = format!("Updated {}", when(r));
                if r.edited_md.is_some() {
                    s.push_str(" · edited");
                }
                plain(s)
            }
        }
    }

    pub fn update(&mut self, message: Message) -> Action {
        match message {
            Message::Retry(kind) => match (&self.data, self.slot(kind)) {
                (Some(data), Some(slot)) if slot.blocked.is_none() && slot.streaming.is_none() => {
                    Action::Generate(kind, data.week)
                }
                _ => Action::None,
            },
            Message::StartEdit => {
                if let Some(r) = self.ready(ReportKind::Summary)
                    && let Some(text) = r.text()
                {
                    self.editor = Some((r.id, text_editor::Content::with_text(text)));
                }
                Action::None
            }
            Message::EditAction(action) => {
                if let Some((_, editor)) = &mut self.editor {
                    editor.perform(action);
                }
                Action::None
            }
            Message::SaveEdit => match self.editor.take() {
                Some((id, editor)) => Action::SaveEdit(id, Some(editor.text())),
                None => Action::None,
            },
            Message::CancelEdit => {
                self.editor = None;
                Action::None
            }
            Message::DiscardEdit => match self.ready(ReportKind::Summary) {
                Some(r) if r.edited_md.is_some() => Action::SaveEdit(r.id, None),
                _ => Action::None,
            },
            Message::Copy => match self.ready(ReportKind::Summary).and_then(Report::text) {
                Some(text) => Action::Copy(text.to_owned()),
                None => Action::None,
            },
            Message::Export => match self.ready(ReportKind::Summary) {
                Some(r) => Action::Export(r.id, ExportFormat::Markdown),
                None => Action::None,
            },
            Message::LinkClicked(_) => Action::None,
        }
    }

    /// The Work summary's body: the text and its buttons, or the editor.
    /// Empty when there is no summary to show.
    pub fn summary_view(&self) -> Element<'_, Message> {
        let Some(slot) = self.slot(ReportKind::Summary) else {
            return Column::new().into();
        };
        if let Some((_, editor)) = &self.editor {
            let editor = text_editor(editor)
                .on_action(Message::EditAction)
                .min_height(320.0)
                .padding(theme::SPACING)
                .size(theme::TEXT_BODY)
                .style(theme::editor);
            let buttons = row![
                small_button("Save", Message::SaveEdit, theme::primary_button),
                small_button("Cancel", Message::CancelEdit, theme::text_button),
            ]
            .spacing(theme::SPACING / 2.0);
            return column![editor, buttons].spacing(theme::SPACING).into();
        }
        if self.body_src.is_empty() {
            return Column::new().into();
        }
        let mut col = column![md(&self.body, theme::TEXT_BODY)].spacing(theme::SPACING);
        if slot.streaming.is_none()
            && let Some(r) = self.ready(ReportKind::Summary)
        {
            let mut buttons = row![
                small_button("Copy", Message::Copy, theme::secondary_button),
                small_button("Edit", Message::StartEdit, theme::secondary_button),
                small_button("Export", Message::Export, theme::secondary_button),
            ]
            .spacing(theme::SPACING / 2.0)
            .align_y(Center);
            if r.edited_md.is_some() {
                buttons = buttons.push(space::horizontal()).push(small_button(
                    "Discard edit",
                    Message::DiscardEdit,
                    theme::text_button,
                ));
            }
            col = col.push(buttons);
        }
        col.into()
    }

    /// The status line for `kind` as an element (with Retry when offered).
    pub fn status_view(&self, kind: ReportKind) -> Option<Element<'_, Message>> {
        let status = self.status(kind)?;
        let style: fn(&Theme) -> text::Style = if status.error {
            theme::danger
        } else {
            theme::muted
        };
        let mut line = row![text(status.text).size(theme::TEXT_SMALL).style(style)]
            .spacing(theme::SPACING / 2.0)
            .align_y(Center);
        if status.retry {
            line = line.push(
                button(text("Retry").size(theme::TEXT_SMALL))
                    .padding([2, 8])
                    .style(theme::text_button)
                    .on_press(Message::Retry(kind)),
            );
        }
        Some(line.into())
    }
}

fn small_button<'a>(
    label: &'a str,
    message: Message,
    style: fn(&Theme, button::Status) -> button::Style,
) -> Element<'a, Message> {
    button(text(label).size(theme::TEXT_SMALL + 1.0))
        .padding([6, 12])
        .style(style)
        .on_press(message)
        .into()
}

fn first_line(s: &str) -> &str {
    s.trim().lines().next().unwrap_or("")
}

/// "Mon 14:02".
fn when(report: &Report) -> String {
    report
        .created_at
        .to_zoned_datetime(jiff::tz::TimeZone::system())
        .strftime("%a %H:%M")
        .to_string()
}

/// Renders parsed Markdown with the app's font and accent; links are
/// reported as `LinkClicked` and ignored.
pub fn md(content: &markdown::Content, size: f32) -> Element<'_, Message> {
    let style = markdown::Style {
        font: theme::FONT,
        inline_code_highlight: markdown::Highlight {
            background: color!(0x78716c, 0.2).into(),
            border: border::rounded(4),
        },
        inline_code_padding: Padding::from([0, 2]),
        inline_code_color: theme::ACCENT,
        inline_code_font: Font::MONOSPACE,
        code_block_font: Font::MONOSPACE,
        link_color: theme::ACCENT,
    };
    // iced's defaults (h1 twice the body) are too loud inside a panel.
    let settings = markdown::Settings {
        h1_size: (size * 1.4).into(),
        h2_size: (size * 1.15).into(),
        h3_size: (size * 1.1).into(),
        h4_size: size.into(),
        code_size: (size * 0.9).into(),
        spacing: (size * 0.75).into(),
        ..markdown::Settings::with_text_size(size, style)
    };
    markdown::view(content.items(), settings).map(Message::LinkClicked)
}

#[cfg(test)]
mod tests {
    use super::*;
    use jiff::Timestamp;
    use jiff::civil::date;

    fn week() -> WeekRef {
        WeekRef::new(date(2026, 11, 16))
    }

    fn report(id: ReportId, kind: ReportKind, text: &str) -> Report {
        Report {
            id,
            kind,
            week_start: week().start,
            status: ReportStatus::Ready,
            digest_json: "{}".into(),
            content_md: Some(text.into()),
            edited_md: None,
            model: Some("test-model".into()),
            endpoint_host: None,
            prompt_version: 4,
            error: None,
            created_at: Timestamp::UNIX_EPOCH,
        }
    }

    fn failed(id: ReportId, kind: ReportKind) -> Report {
        Report {
            status: ReportStatus::Failed,
            content_md: None,
            error: Some("timed out\nmore".into()),
            ..report(id, kind, "")
        }
    }

    fn slot(kind: ReportKind, versions: Vec<Report>) -> ReportSlot {
        ReportSlot {
            kind,
            versions,
            streaming: None,
            blocked: None,
            empty: false,
            stale: false,
        }
    }

    fn data(slots: Vec<ReportSlot>) -> ReportPanelData {
        ReportPanelData {
            week: week(),
            week_label: "Week 47".into(),
            slots,
        }
    }

    const PLAN: &str =
        r#"{"focus": "Ship it", "tasks": [{"id": 3, "day": "2026-11-18", "why": "due Thu"}]}"#;

    #[test]
    fn plan_is_parsed_and_status_says_when() {
        let mut p = ReportPanel::new();
        p.load(data(vec![slot(
            ReportKind::Plan,
            vec![report(1, ReportKind::Plan, PLAN)],
        )]));
        let rec = p.recommendation().unwrap();
        assert_eq!(rec.focus, "Ship it");
        assert_eq!(rec.tasks[0].id, 3);
        assert!(p.unparsed_plan().is_none());
        assert!(
            p.status(ReportKind::Plan)
                .unwrap()
                .text
                .starts_with("Updated ")
        );

        p.load(data(vec![slot(
            ReportKind::Plan,
            vec![report(2, ReportKind::Plan, "## Focus\nprose")],
        )]));
        assert!(p.recommendation().is_none());
        assert_eq!(p.unparsed_plan(), Some("## Focus\nprose"));
    }

    #[test]
    fn statuses() {
        let mut p = ReportPanel::new();
        let mut s = slot(ReportKind::Summary, vec![]);
        s.blocked = Some("the API key is locked.".into());
        p.load(data(vec![s.clone()]));
        assert_eq!(
            p.status(ReportKind::Summary).unwrap().text,
            "Can't update: the API key is locked."
        );

        // Blocked but up to date: just when it updated.
        s.versions = vec![report(1, ReportKind::Summary, "x")];
        p.load(data(vec![s.clone()]));
        assert!(
            p.status(ReportKind::Summary)
                .unwrap()
                .text
                .starts_with("Updated")
        );

        s.blocked = None;
        s.streaming = Some(String::new());
        p.load(data(vec![s.clone()]));
        assert_eq!(p.status(ReportKind::Summary).unwrap().text, "Updating…");

        s.streaming = None;
        s.stale = true;
        s.versions.insert(0, failed(2, ReportKind::Summary));
        p.load(data(vec![s.clone()]));
        let st = p.status(ReportKind::Summary).unwrap();
        assert_eq!(st.text, "Couldn't update: timed out");
        assert!(st.error && st.retry);
        // The last good text still shows.
        assert_eq!(p.body_src, "x");
        assert_eq!(
            p.update(Message::Retry(ReportKind::Summary)),
            Action::Generate(ReportKind::Summary, week())
        );

        let mut empty = slot(ReportKind::Summary, vec![]);
        empty.empty = true;
        p.load(data(vec![empty]));
        assert_eq!(
            p.status(ReportKind::Summary).unwrap().text,
            "Nothing done this week yet."
        );
    }

    #[test]
    fn edit_save_cancel_and_discard() {
        let mut p = ReportPanel::new();
        p.load(data(vec![slot(
            ReportKind::Summary,
            vec![report(7, ReportKind::Summary, "hello")],
        )]));
        p.update(Message::StartEdit);
        p.update(Message::EditAction(text_editor::Action::Move(
            text_editor::Motion::DocumentEnd,
        )));
        p.update(Message::EditAction(text_editor::Action::Edit(
            text_editor::Edit::Insert('!'),
        )));
        assert_eq!(
            p.update(Message::SaveEdit),
            Action::SaveEdit(7, Some("hello!".into()))
        );
        assert_eq!(p.editor_text(), None);
        p.update(Message::StartEdit);
        p.update(Message::CancelEdit);
        assert_eq!(p.update(Message::SaveEdit), Action::None);
        assert_eq!(p.update(Message::DiscardEdit), Action::None, "not edited");

        let mut edited = report(7, ReportKind::Summary, "hello");
        edited.edited_md = Some("mine".into());
        p.load(data(vec![slot(ReportKind::Summary, vec![edited])]));
        assert_eq!(p.update(Message::Copy), Action::Copy("mine".into()));
        assert_eq!(p.update(Message::DiscardEdit), Action::SaveEdit(7, None));
        assert_eq!(
            p.update(Message::Export),
            Action::Export(7, ExportFormat::Markdown)
        );
    }

    #[test]
    fn new_version_closes_the_editor_but_unrelated_loads_keep_it() {
        let mut p = ReportPanel::new();
        let first = data(vec![slot(
            ReportKind::Summary,
            vec![report(1, ReportKind::Summary, "a")],
        )]);
        p.load(first.clone());
        p.update(Message::StartEdit);
        let mut other = first.clone();
        other.slots[0].stale = true;
        p.load(other);
        assert!(p.editor_text().is_some());
        p.load(data(vec![slot(
            ReportKind::Summary,
            vec![
                report(2, ReportKind::Summary, "b"),
                report(1, ReportKind::Summary, "a"),
            ],
        )]));
        assert!(p.editor_text().is_none());
    }

    #[test]
    fn streaming_text_is_pushed_incrementally() {
        let mut p = ReportPanel::new();
        let streaming = |so_far: &str| {
            let mut s = slot(ReportKind::Summary, vec![]);
            s.streaming = Some(so_far.into());
            data(vec![s])
        };
        p.load(streaming(""));
        let start = p.body_parses;
        p.load(streaming("## High"));
        p.load(streaming("## High"));
        assert_eq!(p.body_parses, start + 1);
        p.load(streaming("## Highlights\n- one"));
        assert_eq!(p.body_parses, start + 2);
        let _ = p.summary_view();
    }

    #[test]
    fn every_state_builds_a_view() {
        let mut p = ReportPanel::new();
        let _ = p.summary_view();
        p.load(data(vec![
            slot(ReportKind::Plan, vec![failed(1, ReportKind::Plan)]),
            slot(
                ReportKind::Summary,
                vec![report(2, ReportKind::Summary, "## Hi")],
            ),
        ]));
        let _ = p.summary_view();
        let _ = p.status_view(ReportKind::Plan);
        p.update(Message::StartEdit);
        let _ = p.summary_view();
    }
}
